// extracts inbound traceparent, forwards it on outbound calls
let currentTraceparent = null;

function traceMiddleware(req, res, next) {
  const tp = req.headers['traceparent'];
  if (tp) {
    currentTraceparent = tp;            // remember it for outbound calls
  } else {
    // no inbound context: start a fresh trace
    const traceId = randomHex(16);      // 16 hex chars
    const spanId = randomHex(16);
    currentTraceparent = `00-${traceId}-${spanId}-01`;
  }
  next();
}

function outboundHeaders() {
  return { traceparent: currentTraceparent };
}

module.exports = { traceMiddleware, outboundHeaders };
